498:   updateProjectiles(dt) {
499:     for (let i = this.projectiles.length - 1; i >= 0; i--) {
500:       const p = this.projectiles[i];
501:       const step = p.speed * dt;
502:       p.traveled += step;
503:       p.mesh.position.addScaledVector(p.dir, step);
504:       p.mesh.position.y = p.from.y + (p.to.y - p.from.y) * Math.min(1, p.traveled / p.distance);
505:       p.mesh.rotation.x += dt * 6;
506:       p.mesh.rotation.y += dt * 4;
507:       p.glow.material.opacity = 0.25 + Math.sin(this.time * 20) * 0.07;
508:       if (Math.random() < dt * 40) {
509:         this.fx.burst(p.mesh.position, p.color, 1, 0.7, 1, { life: 0.35, gravity: 0, up: 0.1 });
510:       }
511:       const pc = this.player?.pos;
512:       const hitPlayer = pc && Math.hypot(pc.x - p.mesh.position.x, pc.z - p.mesh.position.z) < p.radius + 0.7;
513:       if (p.traveled >= p.distance || hitPlayer || p.life <= 0) {
514:         p.onHit?.(p.mesh.position.clone());
515:         this.fx.burst(p.mesh.position, p.color, 14, 5, 1, { life: 0.5, gravity: 2 });
516:         this.scene.remove(p.mesh);
517:         p.mesh.traverse?.((o) => { o.geometry?.dispose(); o.material?.dispose?.(); });
518:         this.projectiles.splice(i, 1);
519:       }
520:       p.life -= dt;
521:     }
522:   }
