524:   spawnZone({ pos, radius, duration, dps, slow, color = 0x6fd8ff }) {
525:     const group = new THREE.Group();
526:     group.position.set(pos.x, 0.06, pos.z);
527:     const ring = new THREE.Mesh(new THREE.RingGeometry(radius * 0.9, radius, 40), new THREE.MeshBasicMaterial({
528:       color, transparent: true, opacity: 0.5, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false,
529:     }));
530:     ring.rotation.x = -Math.PI / 2;
531:     const fill = new THREE.Mesh(new THREE.CircleGeometry(radius, 36), new THREE.MeshBasicMaterial({
532:       color, transparent: true, opacity: 0.1, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false,
533:     }));
