126:   trunk.position.y = 1.1;
127:   trunk.castShadow = true;
128:   g.add(trunk);
129:   const layers = 3;
130:   for (let i = 0; i < layers; i++) {
131:     const r = 1.55 - i * 0.33;
132:     const h = 1.9 - i * 0.25;
133:     const cone = new THREE.Mesh(new THREE.ConeGeometry(r, h, 7), standard(i % 2 ? 0x3d6a3a : 0x467b40));
134:     cone.position.y = 2.2 + i * 1.05;
135:     cone.rotation.y = i * 0.6;
136:     cone.castShadow = true;
137:     g.add(cone);
138:   }
139:   // side branch
140:   const branch = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.11, 1.1, 4), standard(0x4a3526));
141:   branch.position.set(0.5, 1.3, 0.1);
142:   branch.rotation.z = -0.9;
143:   g.add(branch);
144:   g.scale.setScalar(scale);
145:   return g;
146: }
