148: function makeIceSpire(size = 1) {
149:   const g = new THREE.Group();
150:   const geo = new THREE.ConeGeometry(0.5 * size, 3.2 * size, 5);
151:   const mat = new THREE.MeshStandardMaterial({ color: 0x9fd6ec, roughness: 0.25, metalness: 0.15, flatShading: true, transparent: true, opacity: 0.92 });
152:   const m = new THREE.Mesh(geo, mat);
153:   m.position.y = 1.6 * size;
154:   m.rotation.z = rand(-0.12, 0.12);
