183: function makeCampfire() {
184:   const g = new THREE.Group();
185:   for (let i = 0; i < 5; i++) {
186:     const log = new THREE.Mesh(new THREE.CylinderGeometry(0.09, 0.09, 0.9, 5), standard(0x3d2a1d));
187:     log.rotation.z = Math.PI / 2;
