211: export function createArena(id, scene, renderer) {
212:   const isHub = id === 'hub';
213:   const cfg = ARENAS[id] || ARENAS.forest;
214:   const group = new THREE.Group();
215:   scene.add(group);
216: 
217:   scene.fog = new THREE.FogExp2(cfg.fog, cfg.fogDensity);
218:   const sky = skyDome(cfg.skyTop, cfg.skyHorizon, cfg.skyBottom);
219:   group.add(sky);
220: 
221:   // sun / moon disc
222:   const sunGeo = new THREE.CircleGeometry(7, 20);
223:   const sunMat = new THREE.MeshBasicMaterial({ color: id === 'ice' ? 0xd7efff : 0xffd9a0, transparent: true, opacity: 0.85, fog: false, depthWrite: false });
224:   const sun = new THREE.Mesh(sunGeo, sunMat);
225:   sun.position.set(cfg.sunPos[0] * 5, cfg.sunPos[1] * 4.2, cfg.sunPos[2] * 5);
226:   sun.lookAt(0, 0, 0);
227:   group.add(sun);
228: 
229:   // lights
230:   const hemi = new THREE.HemisphereLight(cfg.hemiSky, cfg.hemiGround, cfg.hemiIntensity);
231:   group.add(hemi);
232:   const amb = new THREE.AmbientLight(0xffffff, cfg.ambient);
233:   group.add(amb);
234:   const sunLight = new THREE.DirectionalLight(cfg.sun, cfg.sunIntensity);
235:   sunLight.position.set(...cfg.sunPos);
236:   sunLight.castShadow = true;
237:   sunLight.shadow.mapSize.set(1024, 1024);
238:   sunLight.shadow.camera.left = -22;
239:   sunLight.shadow.camera.right = 22;
240:   sunLight.shadow.camera.top = 22;
241:   sunLight.shadow.camera.bottom = -22;
242:   sunLight.shadow.camera.near = 1;
243:   sunLight.shadow.camera.far = 70;
244:   sunLight.shadow.bias = -0.0018;
245:   group.add(sunLight);
246:   group.add(sunLight.target);
247: 
248:   const ground = makeGround(cfg);
249:   group.add(ground);
250: 
251:   // arena ring marking
252:   const ringGeo = new THREE.RingGeometry(13.2, 13.7, 64);
253:   const ringMat = new THREE.MeshBasicMaterial({ color: id === 'volcano' ? 0xff8a4a : id === 'ice' ? 0x8fd6f2 : 0xd9c89a, transparent: true, opacity: 0.12, side: THREE.DoubleSide, depthWrite: false });
254:   const ring = new THREE.Mesh(ringGeo, ringMat);
255:   ring.rotation.x = -Math.PI / 2;
256:   ring.position.y = 0.06;
257:   group.add(ring);
258: 
259:   const obstacles = [];
260:   const scenery = [];
261:   const dummy = new THREE.Object3D();
262:   const rng = (a, b) => a + Math.random() * (b - a);
263: 
264:   // helper to place props without blocking the start lanes
265:   const clearOfStarts = (x, z, r) => {
266:     const starts = [[0, 12], [0, -8], [0, 2]];
267:     return starts.every(([sx, sz]) => Math.hypot(x - sx, z - sz) > r + 4.2);
268:   };
269: 
270:   // ---------- perimeter cliffs ----------
271:   const cliffColor = id === 'forest' ? 0x3d4a34 : id === 'volcano' ? 0x201514 : id === 'ice' ? 0x7f9aad : 0x3a4934;
272:   for (let i = 0; i < 26; i++) {
273:     const a = (i / 26) * Math.PI * 2 + rng(-0.05, 0.05);
274:     const dist = rng(34, 41);
275:     const size = rng(3.2, 6.5);
276:     const rock = makeRock(size, cliffColor, null);
277:     rock.position.set(Math.cos(a) * dist, -size * 0.25, Math.sin(a) * dist);
278:     rock.rotation.y = rng(0, 6);
279:     scenery.push(rock);
280:     group.add(rock);
281:   }
282: 
283:   // ---------- arena props ----------
284:   if (id === 'forest' || isHub) {
285:     const treeCount = isHub ? 10 : 17;
286:     for (let i = 0; i < treeCount; i++) {
287:       const a = rng(0, Math.PI * 2);
288:       const dist = rng(15, 29);
289:       const x = Math.cos(a) * dist, z = Math.sin(a) * dist;
290:       if (!clearOfStarts(x, z, 2.2)) { i--; continue; }
291:       const tree = makeTree(rng(0.85, 1.35));
292:       tree.position.set(x, 0, z);
293:       tree.rotation.y = rng(0, 6);
294:       group.add(tree);
295:       obstacles.push({ x, z, r: 0.7, h: 4 });
296:     }
297:     for (let i = 0; i < 9; i++) {
298:       const a = rng(0, Math.PI * 2);
299:       const dist = rng(12, 28);
300:       const x = Math.cos(a) * dist, z = Math.sin(a) * dist;
301:       if (!clearOfStarts(x, z, 1.5)) { i--; continue; }
302:       const size = rng(0.7, 1.8);
303:       const rock = makeRock(size, 0x6b7268, 0x567a45);
304:       rock.position.set(x, 0, z);
305:       rock.rotation.y = rng(0, 6);
306:       group.add(rock);
307:       obstacles.push({ x, z, r: size * 0.92, h: size });
308:     }
309:     // mushrooms / flowers dots
310:     const dotGeo = new THREE.SphereGeometry(0.07, 4, 3);
311:     const dotMat = new THREE.MeshBasicMaterial({ color: 0xffd27a });
312:     for (let i = 0; i < 26; i++) {
313:       const a = rng(0, Math.PI * 2), dist = rng(5, 26);
314:       const d = new THREE.Mesh(dotGeo, Math.random() > 0.5 ? dotMat : new THREE.MeshBasicMaterial({ color: 0xb28bff }));
315:       d.position.set(Math.cos(a) * dist, 0.06, Math.sin(a) * dist);
316:       group.add(d);
317:     }
318:   } else if (id === 'volcano') {
319:     for (let i = 0; i < 14; i++) {
320:       const a = rng(0, Math.PI * 2);
321:       const dist = rng(14, 30);
322:       const x = Math.cos(a) * dist, z = Math.sin(a) * dist;
323:       if (!clearOfStarts(x, z, 2)) { i--; continue; }
324:       const size = rng(0.9, 2.6);
325:       const rock = makeRock(size, 0x2b1d1a, null);
326:       rock.position.set(x, 0, z);
327:       rock.rotation.y = rng(0, 6);
328:       group.add(rock);
329:       obstacles.push({ x, z, r: size * 0.9, h: size });
330:     }
331:     for (let i = 0; i < 5; i++) {
332:       const a = rng(0, Math.PI * 2);
333:       const dist = rng(16, 27);
334:       const x = Math.cos(a) * dist, z = Math.sin(a) * dist;
335:       const pool = makeLavaPool(rng(1.2, 2.6));
336:       pool.position.set(x, 0, z);
337:       group.add(pool);
338:       scenery.push(pool);
339:     }
340:     // jagged spires
341:     for (let i = 0; i < 8; i++) {
342:       const a = rng(0, Math.PI * 2), dist = rng(26, 33);
343:       const spike = new THREE.Mesh(new THREE.ConeGeometry(rng(0.6, 1.4), rng(4, 8), 5), standard(0x241615));
344:       spike.position.set(Math.cos(a) * dist, 2, Math.sin(a) * dist);
345:       spike.rotation.z = rng(-0.15, 0.15);
346:       spike.castShadow = true;
347:       group.add(spike);
348:     }
349:   } else if (id === 'ice') {
350:     for (let i = 0; i < 16; i++) {
351:       const a = rng(0, Math.PI * 2);
352:       const dist = rng(14, 30);
353:       const x = Math.cos(a) * dist, z = Math.sin(a) * dist;
354:       if (!clearOfStarts(x, z, 2)) { i--; continue; }
355:       const spire = makeIceSpire(rng(0.7, 2.0));
356:       spire.position.set(x, 0, z);
357:       spire.rotation.y = rng(0, 6);
358:       group.add(spire);
359:       obstacles.push({ x, z, r: 0.7, h: 3 });
360:     }
361:     for (let i = 0; i < 8; i++) {
362:       const a = rng(0, Math.PI * 2);
363:       const dist = rng(13, 28);
364:       const x = Math.cos(a) * dist, z = Math.sin(a) * dist;
365:       if (!clearOfStarts(x, z, 1.6)) { i--; continue; }
366:       const size = rng(0.9, 2.2);
367:       const rock = makeRock(size, 0x86a4b6, 0xcfeaf5);
368:       rock.position.set(x, 0, z);
369:       rock.rotation.y = rng(0, 6);
370:       group.add(rock);
371:       obstacles.push({ x, z, r: size * 0.9, h: size });
372:     }
373:     // frozen arch
374:     const archMat = new THREE.MeshStandardMaterial({ color: 0xa6d8ea, roughness: 0.2, metalness: 0.1, flatShading: true, transparent: true, opacity: 0.9 });
375:     for (let side = -1; side <= 1; side += 2) {
376:       const pillar = new THREE.Mesh(new THREE.ConeGeometry(1.1, 9, 5), archMat);
377:       pillar.position.set(side * 8, 4.4, -24);
378:       pillar.rotation.z = side * 0.14;
379:       group.add(pillar);
380:     }
381:   }
382: 
383:   // campfire for hub
384:   let campfire = null;
385:   if (isHub) {
386:     campfire = makeCampfire();
387:     campfire.position.set(3.2, 0, 9);
388:     group.add(campfire);
389:     // tent
390:     const tent = new THREE.Group();
391:     const tentMat = new THREE.MeshStandardMaterial({ color: 0x8a5a3a, roughness: 0.9, flatShading: true });
392:     const body = new THREE.Mesh(new THREE.ConeGeometry(2.2, 2.6, 4), tentMat);
393:     body.position.y = 1.3;
394:     body.rotation.y = Math.PI / 4;
395:     body.castShadow = true;
396:     tent.add(body);
397:     const opening = new THREE.Mesh(new THREE.ConeGeometry(0.8, 1.6, 3), new THREE.MeshBasicMaterial({ color: 0x1a0f08 }));
398:     opening.position.set(0, 0.8, 1.55);
399:     opening.rotation.x = 0.2;
400:     tent.add(opening);
401:     tent.position.set(-4, 0, 10);
402:     tent.rotation.y = 0.4;
403:     group.add(tent);
404:     // crates
405:     for (let i = 0; i < 3; i++) {
406:       const crate = new THREE.Mesh(new THREE.BoxGeometry(0.7, 0.7, 0.7), standard(0x6a4a2e));
407:       crate.position.set(-2.4 + i * 0.8, 0.35, 7.5 + (i % 2) * 0.7);
408:       crate.rotation.y = rng(0, 1);
409:       crate.castShadow = true;
410:       group.add(crate);
411:     }
412:   }
413: 
414:   // ---------- grass ----------
415:   let grass = null;
416:   let grassData = [];
417:   const grassCount = cfg.grassCount || 0;
418:   if (grassCount > 0) {
419:     const bladeGeo = new THREE.PlaneGeometry(0.13, 0.75, 1, 2);
420:     bladeGeo.translate(0, 0.375, 0);
421:     const bladeMat = new THREE.MeshLambertMaterial({ color: 0x6b9a4e, side: THREE.DoubleSide });
422:     grass = new THREE.InstancedMesh(bladeGeo, bladeMat, grassCount);
423:     grass.castShadow = false;
424:     grass.frustumCulled = false;
425:     group.add(grass);
426:     for (let i = 0; i < grassCount; i++) {
427:       const a = rng(0, Math.PI * 2), dist = rng(4.5, 31);
428:       const x = Math.cos(a) * dist, z = Math.sin(a) * dist;
429:       grassData.push({ x, z, phase: rng(0, 6.5), scale: rng(0.7, 1.9), rot: rng(0, 3.1) });
430:       dummy.position.set(x, 0, z);
431:       dummy.rotation.set(0, grassData[i].rot, 0);
432:       dummy.scale.setScalar(grassData[i].scale);
433:       dummy.updateMatrix();
434:       grass.setMatrixAt(i, dummy.matrix);
435:     }
436:     grass.instanceMatrix.needsUpdate = true;
437:     const snowGrass = id === 'ice';
438:     if (snowGrass) bladeMat.color.set(0x9fc0b8);
439:   }
440: 
441:   // ---------- weather / ambience ----------
442:   const weather = { points: null, data: [], kind: cfg.weather };
443:   if (cfg.weather === 'ash' || cfg.weather === 'snow' || cfg.weather === 'leaves') {
444:     const count = id === 'volcano' ? 520 : 460;
445:     const geo = new THREE.BufferGeometry();
446:     const arr = new Float32Array(count * 3);
447:     const col = new Float32Array(count * 3);
448:     const base = cfg.weather === 'snow' ? new THREE.Color(0xffffff) : cfg.weather === 'ash' ? new THREE.Color(0x8e8078) : new THREE.Color(0xd8b06a);
449:     for (let i = 0; i < count; i++) {
450:       const x = rng(-38, 38), y = rng(0, 26), z = rng(-38, 38);
451:       arr[i * 3] = x; arr[i * 3 + 1] = y; arr[i * 3 + 2] = z;
452:       weather.data.push({ vy: cfg.weather === 'snow' ? rng(0.7, 1.7) : cfg.weather === 'ash' ? rng(0.35, 0.9) : rng(0.4, 1.1), drift: rng(0.2, 0.9), phase: rng(0, 6.5), size: rng(0.5, 1.2) });
453:       const c = base.clone().offsetHSL(0, 0, rng(-0.12, 0.12));
454:       col[i * 3] = c.r; col[i * 3 + 1] = c.g; col[i * 3 + 2] = c.b;
455:     }
456:     geo.setAttribute('position', new THREE.BufferAttribute(arr, 3));
457:     geo.setAttribute('color', new THREE.BufferAttribute(col, 3));
458:     const mat = new THREE.PointsMaterial({
459:       size: cfg.weather === 'snow' ? 0.16 : cfg.weather === 'ash' ? 0.12 : 0.14,
460:       vertexColors: true, transparent: true, opacity: cfg.weather === 'snow' ? 0.85 : 0.7,
461:       map: getMoteTexture(), alphaTest: 0.02,
462:       depthWrite: false, blending: cfg.weather === 'ash' ? THREE.NormalBlending : THREE.AdditiveBlending,
463:       sizeAttenuation: true,
464:     });
465:     const pts = new THREE.Points(geo, mat);
466:     pts.frustumCulled = false;
467:     group.add(pts);
468:     weather.points = pts;
469:     weather.arr = arr;
470:   }
471: 
472:   // fireflies
473:   let fireflies = null, fireflyBase = null;
474:   if (cfg.weather === 'fireflies' || id === 'forest') {
475:     const count = isHub ? 42 : 26;
476:     const geo = new THREE.BufferGeometry();
477:     const arr = new Float32Array(count * 3);
478:     fireflyBase = [];
479:     for (let i = 0; i < count; i++) {
480:       const a = rng(0, Math.PI * 2), d = rng(6, 26);
481:       const x = Math.cos(a) * d, z = Math.sin(a) * d, y = rng(0.7, 3.4);
482:       arr[i * 3] = x; arr[i * 3 + 1] = y; arr[i * 3 + 2] = z;
483:       fireflyBase.push({ x, y, z, phase: rng(0, 6.5), amp: rng(0.4, 1.4) });
484:     }
485:     geo.setAttribute('position', new THREE.BufferAttribute(arr, 3));
486:     const mat = new THREE.PointsMaterial({ color: 0xd8ff9a, size: 0.14, map: getMoteTexture(), alphaTest: 0.02, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false });
487:     fireflies = new THREE.Points(geo, mat);
488:     fireflies.frustumCulled = false;
489:     group.add(fireflies);
490:   }
491: 
492:   // embers for volcano
493:   let embers = null;
494:   let emberData = [];
495:   if (id === 'volcano') {
496:     const count = 130;
497:     const geo = new THREE.BufferGeometry();
498:     const arr = new Float32Array(count * 3);
499:     for (let i = 0; i < count; i++) {
500:       const a = rng(0, Math.PI * 2), d = rng(4, 30);
501:       arr[i * 3] = Math.cos(a) * d; arr[i * 3 + 1] = rng(0, 6); arr[i * 3 + 2] = Math.sin(a) * d;
502:       emberData.push({ vy: rng(0.6, 1.8), phase: rng(0, 6.5), drift: rng(-0.4, 0.4) });
503:     }
504:     geo.setAttribute('position', new THREE.BufferAttribute(arr, 3));
505:     const mat = new THREE.PointsMaterial({ color: 0xff7a2a, size: 0.12, map: getMoteTexture(), alphaTest: 0.02, transparent: true, opacity: 0.85, blending: THREE.AdditiveBlending, depthWrite: false });
506:     embers = new THREE.Points(geo, mat);
507:     embers.frustumCulled = false;
508:     group.add(embers);
509:     emberData = { list: emberData, arr };
510:   }
511: 
512:   const grassDummy = new THREE.Object3D();
513:   let t = 0;
514: 
515:   const api = {
516:     id, cfg, group, obstacles, bounds: 31,
517:     playerStart: new THREE.Vector3(0, 0, 12),
518:     monsterStart: new THREE.Vector3(0, 0, -8),
519:     hubPlayer: new THREE.Vector3(0, 0, 2),
520:     name: cfg.name,
521:     update(dt, elapsed, camPos) {
522:       t = elapsed;
523:       if (grass) {
524:         for (let i = 0; i < grassData.length; i++) {
525:           const d = grassData[i];
526:           const sway = Math.sin(t * 1.7 + d.phase) * 0.16 + Math.sin(t * 0.7 + d.phase * 0.6) * 0.08;
527:           grassDummy.position.set(d.x, 0, d.z);
528:           grassDummy.rotation.set(sway * 0.6, d.rot, sway);
529:           grassDummy.scale.set(d.scale, d.scale, d.scale);
530:           grassDummy.updateMatrix();
531:           grass.setMatrixAt(i, grassDummy.matrix);
532:         }
533:         grass.instanceMatrix.needsUpdate = true;
534:       }
535:       if (weather.points) {
536:         const arr = weather.arr;
537:         const cx = camPos ? camPos.x : 0, cz = camPos ? camPos.z : 0;
538:         for (let i = 0; i < weather.data.length; i++) {
539:           const d = weather.data[i];
540:           let y = arr[i * 3 + 1] - d.vy * dt;
541:           let x = arr[i * 3] + Math.sin(t * 0.8 + d.phase) * d.drift * dt;
542:           let z = arr[i * 3 + 2] + Math.cos(t * 0.6 + d.phase) * d.drift * dt * 0.5;
543:           if (y < 0.05) { y = 24; x = cx + rng(-34, 34); z = cz + rng(-34, 34); }
544:           if (Math.abs(x - cx) > 40) x = cx + Math.sign(cx - x) * 38;
545:           if (Math.abs(z - cz) > 40) z = cz + Math.sign(cz - z) * 38;
546:           arr[i * 3] = x; arr[i * 3 + 1] = y; arr[i * 3 + 2] = z;
547:         }
548:         weather.points.geometry.attributes.position.needsUpdate = true;
549:       }
550:       if (fireflies) {
551:         const arr = fireflies.geometry.attributes.position.array;
