458:       this.stamina = Math.min(this.maxStamina, this.stamina + 27 * dt);
459:     }
460: 
461:     // charge aura visuals
462:     if (this.charging) {
463:       this.chargeTime += dt;
464:       const lvl = this._chargeLevelFromTime();
465:       if (lvl !== this.chargeLevel) {
466:         this.chargeLevel = lvl;
467:         if (lvl > 0) this.game.audio.charge(lvl);
468:       }
469:       this.aura.visible = true;
470:       this.aura.material.opacity = 0.1 + lvl * 0.08;
471:       this.aura.rotation.y += dt * 2;
472:       this.aura.scale.setScalar(0.8 + lvl * 0.18 + Math.sin(this.time * 8) * 0.04);
473:       if (Math.random() < dt * (8 + lvl * 8)) {
474:         this.game.fx.burst(this._tmp2.set(this.pos.x, 1.15, this.pos.z), this.weapon.colors.trail, 1, 0.7, 1, { life: 0.5, gravity: -2.5 });
475:       }
476:     } else {
477:       this.aura.visible = false;
478:     }
479:     if (this.demonMode) {
480:       this.demonAura.visible = true;
481:       this.demonAura.material.opacity = 0.09 + Math.sin(this.time * 6) * 0.03;
482:       this.demonAura.rotation.y -= dt * 1.2;
483:     } else {
484:       this.demonAura.visible = false;
485:     }
486: 
487:     // trail during active attack
488:     if (this.state === 'attack' && this.attack && this.attack.phase === 'active') {
489:       this._emitTrail();
490:     }
491: 
492:     this._animate(dt, input, camera, monster);
493:   }
