495:   // ------------------------------------------------------------
496:   _move(dx, dz) {
497:     this.pos.x += dx;
498:     this.pos.z += dz;
499:     const arena = this.game.arena;
500:     const bounds = arena ? arena.bounds - 1.2 : 29;
501:     const d = Math.hypot(this.pos.x, this.pos.z);
502:     if (d > bounds) {
503:       this.pos.x = (this.pos.x / d) * bounds;
504:       this.pos.z = (this.pos.z / d) * bounds;
505:     }
506:     if (arena) {
507:       for (const o of arena.obstacles) {
508:         const dx2 = this.pos.x - o.x, dz2 = this.pos.z - o.z;
509:         const dist = Math.hypot(dx2, dz2);
510:         const min = o.r + 0.45;
511:         if (dist < min && dist > 0.0001) {
512:           this.pos.x = o.x + (dx2 / dist) * min;
513:           this.pos.z = o.z + (dz2 / dist) * min;
514:         }
515:       }
516:     }
517:     this.root.position.set(this.pos.x, 0, this.pos.z);
518:   }
519: 
520:   _drainStamina(n) {
521:     this.stamina = Math.max(0, this.stamina - n);
522:     this.staminaDelay = 0.6;
523:   }
524: 
525:   _beginCombo() {
526:     let idx = 0;
527:     if (this.comboTimer > 0) idx = Math.min(2, this.comboIndex + 1);
528:     this._startAttack(this.weapon.combo[idx], idx, false);
529:     this.game.audio.swing(this.weaponId, idx > 0);
530:   }
531: 
532:   _startFinisher() {
533:     this._startAttack(this.weapon.finisher, 2, true);
534:     this.game.audio.swing(this.weaponId, true);
535:     this.game.ui.announce(this.weapon.finisher.name.toUpperCase(), '', 1.1);
536:   }
537: 
538:   _startAttack(def, index, finisher = false) {
539:     this._autoAim();
540:     this.state = 'attack';
541:     this.attack = {
542:       def, index, finisher,
543:       phase: 'windup', timer: 0,
544:       hitsDone: 0, tickTimer: 0,
545:       lungeSign: 1,
546:     };
547:     this.comboIndex = index;
548:     this.comboTimer = 0;
549:     this.queued = false;
550:     this.queuedFinisher = false;
551:     this.charging = false;
552:     this.chargeTime = 0;
553:     this.chargeLevel = 0;
554:     this._attackTime = 0;
555:   }
556: 
557:   _beginCharge() {
558:     if (this.state !== 'idle') return;
559:     this.state = 'charge';
560:     this.charging = true;
561:     this.chargeTime = 0;
562:     this.chargeLevel = 0;
563:     this.attack = null;
564:     this.comboIndex = 0;
565:     this.comboTimer = 0;
566:   }
567: 
568:   _chargeLevelFromTime() {
569:     const t = this.weapon.charge.times;
570:     if (this.chargeTime >= t[3]) return 3;
571:     if (this.chargeTime >= t[2]) return 2;
572:     if (this.chargeTime >= t[1]) return 1;
573:     return 0;
574:   }
575: 
576:   _releaseCharge() {
577:     const lvl = Math.max(0, this._chargeLevelFromTime());
578:     const cd = this.weapon.charge;
579:     const def = {
580:       ...cd,
581:       dmg: cd.dmg[lvl],
582:       name: cd.name[lvl],
583:       isCharged: lvl,
584:     };
585:     this.charging = false;
586:     this.chargeTime = 0;
587:     this.chargeLevel = 0;
588:     this._startAttack(def, 0, false);
589:     this.game.audio.swing(this.weaponId, true);
590:     this.game.ui.announce(def.name.toUpperCase(), '', 1.4);
591:     if (lvl >= 3) this.game.shake(0.5, 0.3);
592:   }
593: 
594:   _updateCharge(dt, input) {
595:     if (!input.held.attack) this._releaseCharge();
596:   }
597: 
598:   _dualSpecial() {
599:     if (!this.demonMode) {
600:       if (this.stamina < 15) { this.game.ui.hint('Not enough stamina', 1.2); return; }
601:       this._drainStamina(15);
602:       this.demonMode = true;
603:       this.game.audio.notify();
604:       this.game.ui.announce('DEMON MODE', '', 1.4);
605:       this.game.fx.burst(this._tmp2.set(this.pos.x, 1.0, this.pos.z), 0xb28bff, 18, 5, 1, { life: 0.7, gravity: -1 });
606:     } else {
607:       if (this.state === 'attack') { this.queuedFinisher = true; return; }
608:       if (this.stamina < 20) { this.game.ui.hint('Not enough stamina', 1.2); return; }
609:       this._drainStamina(20);
610:       this._startFinisher();
611:     }
612:   }
613: 
614:   _updateAttack(dt, monster) {
615:     const a = this.attack;
616:     if (!a) { this.state = 'idle'; return; }
617:     const def = a.def;
618:     const speedMul = (this.demonMode ? this.weapon.demon.speed : 1) * (a.finisher && this.weaponId === 'dualblades' ? 1.15 : 1);
619:     a.timer += dt * speedMul;
620:     const total = def.windup + def.active + def.recover;
621: 
622:     // forward lunge handled during windup/active
623:     if (def.lunge && (a.phase === 'windup' || a.phase === 'active')) {
624:       const forward = new THREE.Vector3(Math.sin(this.facing), 0, Math.cos(this.facing));
625:       this._move(forward.x * def.lunge * dt * 0.55, forward.z * def.lunge * dt * 0.55);
626:     }
627: 
628:     if (a.phase === 'windup' && a.timer >= def.windup) {
629:       a.phase = 'active';
630:       a.timer = 0;
631:       a.hitsDone = 0;
632:       a.tickTimer = 0;
633:       this.game.audio.swing(this.weaponId, !!a.finisher || !!def.isCharged);
634:       const flashScale = def.anim === 'spin' || def.anim === 'dance' ? 2.4 : a.finisher ? 1.8 : 1.1;
635:       this.game.fx.slashFlash(this._tmp.set(this.pos.x, 1.0, this.pos.z), this.facing, this.weapon.colors.trail, flashScale, 0.7);
636:       if (def.isCharged >= 2) this.game.shake(0.35, 0.18);
637:     } else if (a.phase === 'active') {
638:       const hits = def.hits || 1;
639:       if (def.hits) {
640:         a.tickTimer -= dt;
641:         if (a.tickTimer <= 0 && a.hitsDone < def.hits) {
642:           this._checkHit(monster, def, a);
643:           a.hitsDone++;
644:           a.tickTimer = def.hitInterval || (def.active / def.hits);
645:         }
646:       } else if (a.hitsDone === 0) {
647:         this._checkHit(monster, def, a);
648:         a.hitsDone = 1;
649:       }
650:       if (this.demonMode && this.weaponId === 'dualblades' && a.index === 2 && !a.flurryDone && a.hitsDone >= 1 && !a.finisher) {
651:         a.flurryDone = true;
652:         const fl = this.weapon.demon.flurry;
653:         for (let i = 0; i < fl.hits; i++) {
654:           setTimeout(() => {
655:             if (this.state === 'attack' || this.state === 'idle') {
656:               this._checkHit(monster, { ...def, dmg: fl.dmg, reach: def.reach }, { index: a.index, finisher: false });
657:             }
658:           }, 90 + i * 95);
659:         }
660:       }
661:       if (a.timer >= def.active) {
662:         a.phase = 'recover';
663:         a.timer = 0;
664:       }
665:     } else if (a.phase === 'recover') {
666:       if (a.timer >= def.recover) {
667:         this._endAttack();
668:         return;
669:       }
670:       if (a.timer > def.recover * 0.38) {
671:         if (this.queuedFinisher && this.weaponId !== 'dualblades') {
672:           this.queuedFinisher = false;
673:           this.queued = false;
674:           this._startFinisher();
675:           return;
676:         }
677:         if (this.queued) {
678:           this.queued = false;
679:           if (this.weaponId === 'greatsword' && this.game.input?.held.attack) {
680:             this._beginCharge();
681:           } else {
682:             this._beginCombo();
683:           }
684:           return;
685:         }
686:       }
687:     }
688:     if (a.timer > total * 2.5) this._endAttack();
689:   }
690: 
691:   _endAttack() {
692:     const idx = this.attack?.index ?? 0;
693:     this.comboIndex = idx;
694:     this.comboTimer = 0.65;
695:     this.attack = null;
696:     this.state = 'idle';
697:     if (this.weaponId === 'greatsword' && this.game.input?.held.attack) {
698:       this._beginCharge();
699:     } else if (this.game.input?.held.attack) {
700:       // mobile-friendly auto combo
701:       this._beginCombo();
702:     }
703:   }
704: 
705:   _checkHit(monster, def, attackInfo) {
706:     if (!monster || monster.dead) return;
707:     const parts = monster.getParts();
708:     const fx = this.game.fx;
709:     const reach = def.reach || 2.5;
710:     const arc = def.arc || 2.0;
711:     const targets = [];
712:     for (const part of parts) {
713:       if (part.broken && part.id !== 'body' && Math.random() < 0.25) continue;
714:       const wp = part.obj.getWorldPosition(new THREE.Vector3());
715:       const dx = wp.x - this.pos.x;
716:       const dz = wp.z - this.pos.z;
717:       const dist = Math.hypot(dx, dz);
718:       if (dist > reach + part.radius) continue;
719:       const ang = Math.atan2(dx, dz);
720:       const diff = Math.abs(angleDiff(ang, this.facing));
721:       const partAng = Math.atan2(part.radius, Math.max(0.6, dist)) * 0.9;
722:       if (diff > arc / 2 + partAng) continue;
723:       if (wp.y > 6 || wp.y < -1) continue;
724:       targets.push({ part, dist, wp });
725:     }
726:     targets.sort((a, b) => a.dist - b.dist);
727:     const selected = targets.slice(0, 3);
728:     for (const t of selected) {
729:       const base = (typeof def.dmg === 'number' ? def.dmg : 10) * this.dmgScale * (this.demonMode ? this.weapon.demon.damage : 1);
730:       this.damageDealt += base;
731:       this.game.playerHit({
732:         part: t.part,
733:         base,
734:         def,
735:         worldPos: t.wp,
736:         finisher: !!attackInfo?.finisher,
737:         charged: !!def.isCharged,
738:         demon: this.demonMode,
739:       });
740:       fx.spark(t.wp, this.weapon.colors.trail, !!attackInfo?.finisher || def.isCharged >= 2);
741:     }
742:     if (!selected.length) {
743:       // small whiff dust at weapon range
744:       const fxPos = new THREE.Vector3(this.pos.x + Math.sin(this.facing) * reach * 0.7, 0.5, this.pos.z + Math.cos(this.facing) * reach * 0.7);
745:       fx.dust(fxPos, 2, 0x8d8168);
746:     }
747:   }
748: 
749:   _emitTrail() {
750:     const hand = this.weaponId === 'dualblades' ? (Math.floor(this.time * 14) % 2 ? this.weaponL : this.weaponR) : this.weaponR;
751:     const w = hand || this.weaponR;
752:     if (!w) return;
753:     const tip = w.getObjectByName('tip');
754:     const base = w.getObjectByName('base');
755:     if (!tip || !base) return;
756:     const tipPos = tip.getWorldPosition(this._tmp);
757:     const basePos = base.getWorldPosition(this._tmp2);
758:     this.trail.add(basePos, tipPos, 0.2);
759:     if (this.weaponId === 'dualblades' && this.weaponL) {
760:       const tip2 = this.weaponL.getObjectByName('tip');
761:       const base2 = this.weaponL.getObjectByName('base');
762:       if (tip2 && base2) this.trail.add(base2.getWorldPosition(new THREE.Vector3()), tip2.getWorldPosition(new THREE.Vector3()), 0.16);
763:     }
764:   }
