766:   // ------------------------------------------------------------
767:   usePotion() {
768:     if (this.potions <= 0) { this.game.ui.hint('No potions left', 1.4); return; }
769:     if (this.hp >= this.maxHp) { this.game.ui.hint('Health is full', 1.4); return; }
770:     if (this.state === 'dodge' || this.state === 'dead') return;
771:     this.potions--;
772:     this.state = 'drink';
773:     this.potionTimer = 0;
774:     this.potionHealed = false;
775:     this.charging = false;
776:     this.chargeTime = 0;
777:     this.chargeLevel = 0;
778:     this.attack = null;
779:     this.game.audio.potion();
780:     this.game.ui.subtitle('Drinking potion…', 1.0);
781:   }
