783:   _updatePotion(dt) {
784:     this.potionTimer += dt;
785:     if (!this.potionHealed && this.potionTimer >= 0.7) {
786:       this.potionHealed = true;
787:       const heal = Math.min(POTION_HEAL, this.maxHp - this.hp);
788:       this.hp += heal;
789:       this.game.ui.damage(this.game.project(this._tmp.set(this.pos.x, 1.9, this.pos.z)), `+${Math.round(heal)}`, 'heal');
790:       this.game.audio.potion();
791:       this.game.fx.burst(this._tmp.set(this.pos.x, 1.2, this.pos.z), 0x8fe36f, 14, 2.4, 1, { life: 0.8, gravity: -2 });
792:     }
793:     if (this.potionTimer >= 1.25) {
794:       this.state = 'idle';
795:     }
796:   }
