799:   _startDodge(moveVec, moving) {
800:     this._drainStamina(20);
801:     this.state = 'dodge';
802:     this.dodgeTimer = 0;
803:     this.charging = false;
804:     this.attack = null;
805:     this.comboIndex = 0;
806:     this.comboTimer = 0;
807:     if (moving) {
808:       this.rollDir.set(moveVec.x, moveVec.z);
809:       this.facing = Math.atan2(moveVec.x, moveVec.z);
810:     } else {
811:       this.rollDir.set(-Math.sin(this.facing), -Math.cos(this.facing));
812:     }
813:     this.rollDir.normalize();
814:     this.invuln = 0.38;
815:     this.game.audio.dodge();
816:     this.game.fx.dust(this._tmp.set(this.pos.x, 0.15, this.pos.z), 7, 0x9a8d70);
817:   }
818: 
819:   _updateDodge(dt) {
820:     this.dodgeTimer += dt;
821:     const t = Math.min(1, this.dodgeTimer / 0.42);
822:     const sp = 9.5 * (1 - t * 0.6);
823:     this._move(this.rollDir.x * sp * dt, this.rollDir.y * sp * dt);
824:     if (t >= 1) {
825:       this.state = 'idle';
826:       this.dodgeTimer = 0;
827:     } else if (Math.random() < dt * 20) {
828:       this.game.fx.dust(this._tmp.set(this.pos.x, 0.12, this.pos.z), 1, 0x9a8d70);
829:     }
830:   }
