832:   _autoAim() {
833:     const m = this.game.monster;
834:     if (!m || m.dead) return;
835:     const dx = m.pos.x - this.pos.x, dz = m.pos.z - this.pos.z;
836:     const dist = Math.hypot(dx, dz);
837:     if (dist < 1) return;
838:     const ang = Math.atan2(dx, dz);
839:     const diff = Math.abs(angleDiff(ang, this.facing));
840:     if (this.game.lockOn || diff < 2.0 || dist < 6) {
841:       this.facing = ang;
842:     }
843:   }
