845:   // ------------------------------------------------------------
846:   stun(seconds = 1.2) {
847:     if (this.dead || this.state === 'dodge' || this.invuln > 0.2) return;
848:     this.staggerTimer = Math.max(this.staggerTimer, seconds);
849:     this.attack = null;
850:     this.charging = false;
851:     this.chargeTime = 0;
852:     this.chargeLevel = 0;
853:     if (this.state !== 'guard') this.state = 'idle';
854:     this.game.ui.subtitle('Stunned by the roar!', 1.2);
855:   }
856: 
857:   takeDamage(amount, sourcePos, heavy = false) {
858:     if (this.dead) return { result: 'dead' };
859:     if (this.invuln > 0 || this.state === 'dodge') {
860:       return { result: 'dodge' };
861:     }
862:     let dmg = amount;
863:     let result = 'hit';
864:     const toSource = new THREE.Vector2(sourcePos.x - this.pos.x, sourcePos.z - this.pos.z).normalize();
865:     const forward = new THREE.Vector2(Math.sin(this.facing), Math.cos(this.facing));
866:     const facingSource = forward.dot(toSource) > 0.1;
867:     if (this.state === 'guard' && this.weapon.canGuard && facingSource) {
868:       const cost = this.weapon.blockStamina;
869:       if (this.stamina >= cost * 0.5) {
870:         dmg *= (1 - this.weapon.blockReduction);
871:         this._drainStamina(cost);
872:         result = 'block';
873:         this.blockFlash = 0.25;
874:         this.game.audio.impact(0.7, true, 0);
875:         this.game.fx.spark(this._tmp.set(this.pos.x + forward.x * 0.6, 1.2, this.pos.z + forward.y * 0.6), 0xffd58a, true);
876:         this.game.shake(0.15, 0.1);
877:         if (this.stamina <= 0) {
878:           result = 'guardbreak';
879:           this.staggerTimer = 0.8;
880:           this.state = 'idle';
881:           this.game.ui.announce('GUARD BROKEN', 'tired', 1.2);
882:           dmg = amount;
883:         }
884:       } else {
885:         result = 'guardbreak';
886:         this.staggerTimer = 0.8;
887:         this.state = 'idle';
888:       }
889:     }
890:     this.hp = Math.max(0, this.hp - dmg);
891:     this.hurtTimer = 0.3;
892:     if (dmg > 6) this.staggerTimer = Math.max(this.staggerTimer, heavy ? 0.5 : 0.22);
893:     this.invuln = 0.65;
894:     this.charging = false;
895:     this.attack = null;
896:     if (this.state !== 'guard') this.state = 'idle';
897:     if (this.potionTimer > 0) this.potionTimer = 0;
898:     this.game.ui.damage(this.game.project(this._tmp.set(this.pos.x, 1.9, this.pos.z)), `-${Math.round(dmg)}`, 'small');
899:     const away = new THREE.Vector3(this.pos.x - sourcePos.x, 0, this.pos.z - sourcePos.z).normalize();
900:     this.knock.addScaledVector(away, heavy ? 7 : 4.5);
901:     this.game.ui.flash('hurt');
902:     this.game.shake(heavy ? 0.5 : 0.28, heavy ? 0.3 : 0.18);
903:     this.game.audio.impact(0.9, false, 0);
904:     if (this.hp <= 0) {
905:       this.dead = true;
906:       this.state = 'dead';
907:       this.game.onPlayerDeath();
908:     }
909:     return { result, dmg };
910:   }
