913:   _poseReset() {
914:     this.model.rotation.set(0, 0, 0);
915:     this.model.position.set(0, 0, 0);
916:     this.hips.position.y = 0.92 + 0;
917:     this.hips.rotation.set(0, 0, 0);
918:     this.torso.rotation.set(0, 0, 0);
919:     this.head.rotation.set(0, 0, 0);
920:     this.armL.rotation.set(0, 0, 0);
921:     this.armR.rotation.set(0, 0, 0);
922:     this.legL.rotation.set(0, 0, 0);
923:     this.legR.rotation.set(0, 0, 0);
924:     if (this.cape) this.cape.rotation.set(0, 0, 0);
925:   }
926: 
927:   _animate(dt, input, camera, monster) {
928:     if (!this.rigInit) { this._poseReset(); this.rigInit = true; }
929:     const pose = {
930:       hipY: 0, torsoX: 0, torsoY: 0, headX: 0,
931:       armRx: -0.08, armRy: 0, armRz: 0.12,
932:       armLx: -0.08, armLy: 0, armLz: -0.12,
933:       legLx: 0, legRx: 0,
934:       modelRotY: 0, modelRotX: 0,
935:       wRx: 0.42, wRy: 0, wRz: -0.12,
936:       wLx: 0, wLy: -1.15, wLz: 0.2,
937:       capeSwing: 0,
938:     };
939:     if (this.weaponId === 'dualblades') { pose.wRx = 1.35; pose.wRy = 0.1; pose.wRz = 0.15; pose.wLx = 1.35; pose.wLy = -0.1; pose.wLz = -0.15; }
940:     if (this.weaponId === 'swordshield') { pose.wRx = 0.45; pose.wRy = 0; pose.wRz = -0.05; }
941: 
942:     const moving = this.speedSmooth > 0.6;
943:     const moveAmt = clamp(this.speedSmooth / this.weapon.moveSpeed, 0, 1.2);
944:     if (moving) this.walkPhase += dt * (6.5 + this.speedSmooth * 0.7);
945:     const swing = Math.sin(this.walkPhase) * (0.55 + moveAmt * 0.25);
