406:   updateHud(state) {
407:     const h = this.huntEls;
408:     const hpPct = Math.max(0, state.hp / state.maxHp);
409:     const stPct = Math.max(0, state.stamina / state.maxStamina);
410:     const mPct = Math.max(0, state.monsterHp / state.monsterMaxHp);
411:     if (this._lastHud.hp !== hpPct) {
412:       h.hpFill.style.transform = `scaleX(${hpPct})`;
413:       h.hpText.textContent = Math.ceil(state.hp);
414:       h.hp.classList.toggle('low', hpPct < 0.3);
415:       this._lastHud.hp = hpPct;
416:     }
417:     if (this._lastHud.st !== stPct) {
418:       h.stamFill.style.transform = `scaleX(${stPct})`;
419:       h.stamText.textContent = Math.round(state.stamina);
420:       this._lastHud.st = stPct;
421:     }
422:     if (this._lastHud.mhp !== mPct) {
423:       h.monsterFill.style.transform = `scaleX(${mPct})`;
424:       this._lastHud.mhp = mPct;
425:     }
426:     if (this._lastHud.phase !== state.phase) {
427:       const phase = state.phase;
428:       h.monsterPhase.textContent = phase === 'enraged' ? 'ENRAGED' : phase === 'tired' ? 'TIRED' : 'CALM';
429:       h.monsterPhase.className = 'phase-tag ' + (phase === 'normal' ? '' : phase);
430:       this._lastHud.phase = phase;
431:     }
432:     if (this._lastHud.time !== state.time) {
433:       const t = Math.max(0, state.time);
434:       const mm = Math.floor(t / 60).toString().padStart(2, '0');
435:       const ss = Math.floor(t % 60).toString().padStart(2, '0');
436:       h.timerText.textContent = `${mm}:${ss}`;
437:       h.timer.classList.toggle('low', t <= 60);
438:       this._lastHud.time = state.time;
439:     }
440:     if (this._lastHud.items !== state.potions) {
441:       h.itemCount.textContent = state.potions;
442:       h.touchItemCount.textContent = state.potions;
443:       this._lastHud.items = state.potions;
444:     }
445:     if (this._lastHud.combo !== state.combo) {
446:       h.comboMeter.classList.toggle('on', state.combo > 0);
447:       h.comboPips.forEach((p, i) => p.classList.toggle('on', i < state.combo));
448:       this._lastHud.combo = state.combo;
449:     }
450:     if (this._lastHud.charge !== state.charge) {
451:       if (state.charge > 0) {
452:         h.charge.classList.remove('hidden');
453:         h.chargePips.forEach((p, i) => p.classList.toggle('on', i < state.charge));
454:         h.charge.querySelector('b').textContent = ['CHARGE', 'CHARGE I', 'CHARGE II', 'CHARGE III'][Math.min(3, state.charge)];
455:       } else {
456:         h.charge.classList.add('hidden');
457:       }
458:       this._lastHud.charge = state.charge;
459:     }
460:     if (this._lastHud.lock !== state.locked) {
461:       h.lock.classList.toggle('hidden', !state.locked);
462:       h.touchLock.classList.toggle('active', !!state.locked);
463:       this._lastHud.lock = state.locked;
464:     }
465:     if (this._parts && this._lastHud.parts !== state.partsVersion) {
466:       const map = new Map((state.brokenParts || []).map((p) => [p.id, p]));
467:       for (const p of this._parts) {
468:         const chip = h.partChips.querySelector(`[data-part="${p.id}"]`);
469:         if (!chip) continue;
470:         chip.classList.toggle('broken', map.has(p.id));
471:       }
472:       this._lastHud.parts = state.partsVersion;
473:     }
474:   }
