578: 
579: const STUN_PARTICLES = 0x9fd8ff;
580: 
581: export class Monster {
582:   constructor(scene, game, typeId) {
583:     this.scene = scene;
584:     this.game = game;
585:     this.type = MONSTER_TYPES[typeId];
586:     if (!this.type) throw new Error('Unknown monster ' + typeId);
587:     this.id = typeId;
588:     this.maxHealth = this.type.hp;
589:     this.health = this.maxHealth;
590:     this.pos = this.game.arena.monsterStart.clone();
591:     this.yaw = 0;
592:     this.state = 'idle';
593:     this.timer = 0;
594:     this.think = 0.5;
595:     this.phase = 'normal';
596:     this.enraged = false;
597:     this.tired = false;
598:     this.dead = false;
599:     this.dying = false;
600:     this.deathTimer = 0;
601:     this.staggerTimer = 0;
602:     this.staggerMeter = 0;
603:     this.staggerThreshold = 150;
604:     this.height = 0;
605:     this.attack = null;
606:     this.telegraph = null;
607:     this.cooldowns = {};
608:     this.currentSpeed = 0;
609:     this.walkPhase = 0;
610:     this.animLean = 0;
611:     this.animRoll = 0;
612:     this.animJaw = 0;
613:     this.animHead = 0;
614:     this.eyeGlow = 1.3;
615:     this.flinchTimer = 0;
616:     this.restCooldown = 0;
617:     this.tiredTimer = 0;
618:     this.fleeTimer = 0;
619:     this.droolTimer = 0;
620:     this.hitFlash = 0;
621:     this.footstep = 0;
622:     this.time = 0;
623:     this._lastPartPositions = new Map();
624: 
625:     this.parts = this.type.parts.map((p) => ({
626:       ...p,
627:       hpMax: p.hp,
628:       broken: false,
629:       obj: null,
630:     }));
631: 
632:     this._construct();
633:     this._buildParts();
634:     this.root.position.copy(this.pos);
635:     this.root.rotation.y = this.yaw;
636:     this.scene.add(this.root);
637:     this.game.ui.setParts(this.parts.map((p) => ({ id: p.id, label: p.label, weak: p.weak })));
638:   }
639: 
640:   _construct() {
641:     const rig = this.type.build(this.type.palette);
642:     this.rig = rig;
643:     this.root = rig.root;
644:     this.root.scale.setScalar(this.type.scale);
645:     this.body = rig.body;
646:     this.baseY = rig.baseY;
647:     // eye material references
648:     this.eyeMats = [];
649:     rig.root.traverse((o) => {
650:       if (o.isMesh && o.material && o.material.emissive && o.material.emissive.getHex() === this.type.palette.eyes) {
651:         this.eyeMats.push(o.material);
652:       }
653:     });
654:   }
655: 
656:   _buildParts() {
657:     for (const part of this.parts) {
658:       part.obj = this.rig[part.node] || this.rig.bodyHit;
659:     }
660:   }
661: 
662:   getParts() {
663:     return this.parts;
664:   }
665: 
666:   get center() {
667:     return new THREE.Vector3(this.pos.x, 2.2, this.pos.z);
668:   }
669: 
670:   get barPhase() {
671:     return this.phase;
672:   }
673: 
674:   // ------------------------------------------------------------
675:   update(dt, player) {
676:     if (this.dead) return;
677:     this.eyeGlow = damp(this.eyeGlow, this.enraged ? 2.8 : 1.3, 5, dt);
678:     for (const m of this.eyeMats) m.emissiveIntensity = this.eyeGlow;
679:     this.flinchTimer = Math.max(0, this.flinchTimer - dt);
680:     this.hitFlash = Math.max(0, this.hitFlash - dt * 3);
681: 
682:     for (const k of Object.keys(this.cooldowns)) {
683:       this.cooldowns[k] = Math.max(0, this.cooldowns[k] - dt);
684:     }
685:     this.restCooldown = Math.max(0, this.restCooldown - dt);
686: 
687:     if (this.dying) {
688:       this.deathTimer += dt;
689:       this._animate(dt, player);
690:       if (this.deathTimer > 3.6 && !this._deathNotified) {
691:         this._deathNotified = true;
692:         this.game.onMonsterDeathEnd?.();
693:       }
694:       return;
695:     }
696: 
697:     if (this.staggerTimer > 0) {
698:       this.staggerTimer -= dt;
699:       this.state = 'stagger';
700:       this.currentSpeed = damp(this.currentSpeed, 0, 8, dt);
701:       if (this.staggerTimer <= 0) {
702:         this.state = 'chase';
703:         this.think = 0.4;
704:       }
705:       this._animate(dt, player);
706:       return;
707:     }
708: 
709:     const pDist = this._distTo(player);
710:     const toPlayer = new THREE.Vector2(player.pos.x - this.pos.x, player.pos.z - this.pos.z);
711:     const ang = Math.atan2(toPlayer.x, toPlayer.y);
712: 
713:     // phase timers
714:     if (this.tired) {
715:       this.tiredTimer += dt;
716:       this.droolTimer += dt;
717:       if (this.droolTimer > 0.55 && this.state !== 'run') {
718:         this.droolTimer = 0;
719:         const mouth = this._mouthPos();
720:         this.game.fx.burst(mouth, 0xa8d8e8, 2, 0.8, 1, { life: 0.7, gravity: 8, up: 0 });
721:       }
722:     }
723: 
724:     switch (this.state) {
725:       case 'idle':
726:         this.think -= dt;
727:         this.currentSpeed = damp(this.currentSpeed, 0, 6, dt);
728:         if (this.think <= 0) this.state = 'chase';
729:         this._turnToward(ang, dt, 1.2);
730:         break;
731:       case 'chase': {
732:         this._chase(dt, player, pDist, ang);
733:         break;
734:       }
735:       case 'windup':
736:         this.currentSpeed = damp(this.currentSpeed, 0, 10, dt);
737:         this._updateWindup(dt, player);
738:         break;
739:       case 'active':
740:         this._updateActive(dt, player);
741:         break;
742:       case 'recover':
743:         this.currentSpeed = damp(this.currentSpeed, 0, 6, dt);
744:         this.timer += dt;
745:         if (this.timer >= (this.attack?.def.recover || 1)) {
746:           this.state = 'chase';
747:           this.attack = null;
748:           this.think = this.enraged ? 0.2 : 0.5;
749:         }
750:         break;
751:       case 'flee':
752:         this._flee(dt, player);
753:         break;
754:       case 'rest':
755:         this.currentSpeed = damp(this.currentSpeed, 0, 6, dt);
756:         this.timer += dt;
757:         this.health = Math.min(this.maxHealth * 0.34, this.health + 16 * dt);
758:         if (this.timer > 5.5 || this.health >= this.maxHealth * 0.34 - 0.5) {
759:           this.state = 'chase';
760:           this.timer = 0;
761:           this.restCooldown = 12;
762:           this.think = 0.5;
763:         }
764:         break;
765:       case 'roar':
766:         // same as windup-free scripted roar
767:         this.timer += dt;
768:         if (this.timer > 1.5) { this.state = 'chase'; this.attack = null; }
769:         break;
770:       case 'dying':
771:         break;
772:     }
773: 
774:     // movement collisions
775:     if (Math.abs(this.currentSpeed) > 0.05 && (this.state === 'chase' || this.state === 'flee')) {
776:       const forward = new THREE.Vector2(Math.sin(this.yaw), Math.cos(this.yaw));
777:       this._move(forward.x * this.currentSpeed * dt, forward.y * this.currentSpeed * dt);
778:       this.walkPhase += dt * (3 + this.currentSpeed * 1.1);
779:       this.footstep += dt;
780:       if (this.footstep > (this.enraged ? 0.34 : 0.46)) {
781:         this.footstep = 0;
782:         this.game.audio.monsterStep(0, this.id === 'icebehemoth');
783:         this.game.fx.dust(new THREE.Vector3(this.pos.x, 0.1, this.pos.z), 2, this.id === 'ice' ? 0xccdde6 : 0x8f8168);
784:       }
785:     } else {
786:       this.walkPhase += dt * 1.2;
787:     }
788: 
789:     this._animate(dt, player);
790:   }
791: 
792:   _distTo(player) {
793:     return Math.hypot(player.pos.x - this.pos.x, player.pos.z - this.pos.z);
794:   }
795: 
796:   _turnToward(ang, dt, mul = 1) {
797:     const speed = this.type.turn * mul * (this.enraged ? 1.3 : 1) * (this.tired ? 0.7 : 1);
798:     const d = angleDiff(ang, this.yaw);
799:     this.yaw += clamp(d, -speed * dt, speed * dt);
800:     this.root.rotation.y = this.yaw;
801:   }
802: 
803:   _move(dx, dz) {
804:     this.pos.x += dx;
805:     this.pos.z += dz;
806:     const arena = this.game.arena;
807:     const bounds = arena.bounds - 2;
808:     const d = Math.hypot(this.pos.x, this.pos.z);
809:     if (d > bounds) {
810:       this.pos.x = (this.pos.x / d) * bounds;
811:       this.pos.z = (this.pos.z / d) * bounds;
812:     }
813:     for (const o of arena.obstacles) {
814:       const dx2 = this.pos.x - o.x, dz2 = this.pos.z - o.z;
815:       const dist = Math.hypot(dx2, dz2);
816:       const min = o.r + this.type.radius * 0.8;
817:       if (dist < min && dist > 0.0001) {
818:         this.pos.x = o.x + (dx2 / dist) * min;
819:         this.pos.z = o.z + (dz2 / dist) * min;
820:       }
821:     }
822:     this.root.position.set(this.pos.x, 0, this.pos.z);
823:   }
824: 
825:   _chase(dt, player, dist, ang) {
826:     this.think -= dt;
827:     const tiredMul = this.tired ? 0.62 : 1;
828:     const enrageMul = this.enraged ? 1.18 : 1;
829:     const speed = this.type.chaseSpeed * tiredMul * enrageMul;
830:     const pref = this.type.preferred;
831: 
832:     if (this.tired && this.restCooldown <= 0 && this.tiredTimer > 5) {
833:       this.state = 'flee';
834:       this.timer = 0;
835:       this.fleeDirection = 1;
836:       this.game.ui.announce('THE BEAST FLEES', 'tired', 1.8);
837:       return;
838:     }
839: 
840:     // movement
841:     if (dist > pref + 1.4) {
842:       this._turnToward(ang, dt, 1.4);
843:       this.currentSpeed = damp(this.currentSpeed, speed, 4, dt);
844:     } else if (dist < pref - 2.2) {
845:       this._turnToward(ang + Math.PI, dt, 0.6);
846:       this.currentSpeed = damp(this.currentSpeed, -speed * 0.5, 4, dt);
847:     } else {
848:       this._turnToward(ang, dt, 1.2);
849:       const strafe = Math.sin(this.time * 0.6) > 0 ? 0.55 : -0.55;
850:       this.currentSpeed = damp(this.currentSpeed, 0, 6, dt);
851:       // small circling
852:       const side = new THREE.Vector2(Math.cos(ang), -Math.sin(ang)).multiplyScalar(strafe * 1.1 * tiredMul);
853:       this._move(side.x * dt, side.y * dt);
854:     }
855: 
856:     if (this.think <= 0 && dist < 30) {
857:       const atk = this._chooseAttack(dist);
858:       if (atk) {
859:         this._beginAttack(atk, player);
860:         return;
861:       }
862:       this.think = 0.35;
863:     }
864:   }
865: 
866:   _flee(dt, player) {
867:     this.timer += dt;
868:     const awayAng = Math.atan2(this.pos.x - player.pos.x, this.pos.z - player.pos.z);
869:     this._turnToward(awayAng, dt, 1.4);
870:     this.currentSpeed = damp(this.currentSpeed, (this.tired ? 4.4 : 6) * 0.95, 3, dt);
871:     if (this.timer > 3.4 || this._distTo(player) > 19) {
872:       this.currentSpeed = 0;
873:       this.state = 'rest';
874:       this.timer = 0;
875:       this.game.ui.announce('RESTING', 'tired', 1.4);
876:     }
877:   }
878: 
879:   _chooseAttack(dist) {
880:     const candidates = this.type.attacks.filter((a) => {
881:       if (dist < a.min || dist > a.max) return false;
882:       if ((this.cooldowns[a.id] || 0) > 0) return false;
883:       if (this.tired && a.id === 'roar') return false;
884:       return true;
885:     });
886:     if (!candidates.length) return null;
887:     // prefer attacks with good range fit and enrage combos
888:     candidates.sort((a, b) => {
889:       const sa = Math.abs(dist - (a.max + a.min) / 2) + Math.random() * 4;
890:       const sb = Math.abs(dist - (b.max + b.min) / 2) + Math.random() * 4;
891:       return sa - sb;
892:     });
893:     return candidates[0];
894:   }
895: 
896:   // ------------------------------------------------------------
897:   _beginAttack(atk, player) {
898:     this.state = 'windup';
899:     this.timer = 0;
900:     this.currentSpeed = 0;
901:     this.attack = {
902:       def: atk, phase: 'windup', timer: 0, hit: false, tick: 0,
903:       target: player.pos.clone(),
904:       center: atk.center || 'self',
905:       breathTicks: 0,
906:     };
907:     this._turnToward(Math.atan2(player.pos.x - this.pos.x, player.pos.z - this.pos.z), 0.25, 2);
908:     this.think = 0.25;
909:     if (atk.telegraph) this._makeTelegraph(atk, player);
910:     if (atk.id === 'roar') {
911:       this.game.audio.roar();
912:       this.game.shake(0.4, 0.4);
913:     } else if (atk.id === 'fireball' || atk.id === 'breath') {
914:       this.game.audio.fire();
915:     } else if (atk.id === 'shards' || atk.id === 'freeze') {
916:       this.game.audio.ice();
917:     } else {
918:       this.game.audio.monsterStep(0, true);
919:     }
920:     this.cooldowns[atk.id] = atk.cd * (this.enraged ? 0.72 : 1) * (this.tired ? 1.35 : 1);
921:   }
922: 
923:   _makeTelegraph(atk, player) {
924:     const t = atk.shape;
925:     const yawAt = Math.atan2(player.pos.x - this.pos.x, player.pos.z - this.pos.z);
926:     let center = this.pos.clone();
927:     if (atk.center === 'target') {
928:       center = this.attack.target.clone();
929:       // clamp target inside arena
930:       const d = Math.hypot(center.x, center.z);
931:       if (d > this.game.arena.bounds - 2) {
932:         center.x *= (this.game.arena.bounds - 2) / d;
933:         center.z *= (this.game.arena.bounds - 2) / d;
934:       }
935:     }
936:     const col = this.id === 'firewyvern' ? 0xff5a22 : this.id === 'icebehemoth' ? 0x4fc8ff : 0xff3b22;
937:     if (atk.telegraph === 'circle') {
938:       this.telegraph = this.game.fx.telegraphCircle(center, t.radius, atk.windup + atk.active * (atk.breath ? 0.6 : 0.4), col);
939:     } else if (atk.telegraph === 'cone') {
940:       this.telegraph = this.game.fx.telegraphCone(this.pos, yawAt, t.radius, t.angle, atk.windup + (atk.breath ? atk.active : 0.1), col);
941:     } else if (atk.telegraph === 'line') {
942:       this.telegraph = this.game.fx.telegraphLine(this.pos, yawAt, t.length, t.width, atk.windup + atk.active, col);
943:       this.attack.lineYaw = yawAt;
944:     }
945:     this.attack.telegraphYaw = yawAt;
946:   }
947: 
948:   _updateWindup(dt, player) {
949:     const a = this.attack;
950:     if (!a) { this.state = 'chase'; return; }
951:     a.timer += dt;
952:     const def = a.def;
953:     // slight tracking early in the windup
954:     if (a.timer < def.windup * (def.track ?? 0.5)) {
955:       const ang = Math.atan2(player.pos.x - this.pos.x, player.pos.z - this.pos.z);
956:       this._turnToward(ang, dt, 0.7);
957:     }
958:     // dive rises
959:     if (def.dive) {
960:       const t = clamp(a.timer / def.windup, 0, 1);
961:       this.height = Math.sin(t * Math.PI * 0.5) * 4.2;
962:       // drift towards target
963:       if (t > 0.4) {
964:         const k = 1 - Math.exp(-dt * 3.5);
965:         this.pos.x = lerp(this.pos.x, a.target.x, k);
966:         this.pos.z = lerp(this.pos.z, a.target.z, k);
967:         this.root.position.set(this.pos.x, 0, this.pos.z);
968:         if (this.telegraph) this.telegraph.mesh.position.set(this.pos.x, 0.045, this.pos.z);
969:       }
970:       if (Math.random() < dt * 20) this.game.fx.burst(this._mouthPos(), 0xff8a3a, 2, 1.5, 1, { life: 0.5, gravity: -2 });
971:     }
972:     if (a.timer >= def.windup) {
973:       a.phase = 'active';
974:       a.timer = 0;
975:       this.state = 'active';
976:       this.timer = 0;
977:       this._removeTelegraph();
978:       this._attackActiveStart(player);
979:     }
980:   }
981: 
982:   _updateActive(dt, player) {
983:     const a = this.attack;
984:     if (!a) { this.state = 'recover'; return; }
985:     const def = a.def;
986:     a.timer += dt;
987: 
988:     if (def.dash) {
989:       // charging rush
990:       const fwd = new THREE.Vector2(Math.sin(this.yaw), Math.cos(this.yaw));
991:       this._move(fwd.x * def.dash * dt, fwd.y * def.dash * dt);
992:       this.walkPhase += dt * 15;
993:       if (Math.random() < dt * 30) this.game.fx.dust(new THREE.Vector3(this.pos.x, 0.15, this.pos.z), 2, 0x8f8168);
994:       if (!a.hit) {
995:         const d = this._distTo(player);
996:         if (d < this.type.radius + 1.1) {
997:           a.hit = true;
998:           this.game.player.takeDamage(def.damage, this.pos, true);
999:           this.game.fx.shockwave(this.pos, 3, 0xffb875, 0.4);
1000:         }
1001:       }
1002:       if (a.timer >= def.active) {
1003:         this.game.fx.shockwave(this.pos, 3.2, 0xbbaa88, 0.5);
1004:         this.game.shake(0.25, 0.2);
1005:       }
1006:     } else if (def.dive) {
1007:       const t = clamp(a.timer / Math.max(0.28, def.active * 0.6), 0, 1);
1008:       this.height = 4.2 * (1 - t);
1009:       if (!a.hit && t >= 1) {
1010:         a.hit = true;
1011:         this.height = 0;
1012:         this.game.fx.shockwave(this.pos, def.shape.radius * 1.4, 0xffa460, 0.6);
1013:         this.game.fx.dust(new THREE.Vector3(this.pos.x, 0.2, this.pos.z), 24, 0x9a7a5a);
1014:         this.game.shake(0.7, 0.4);
1015:         if (this._distTo(player) <= def.shape.radius) this.game.player.takeDamage(def.damage, this.pos, true);
1016:       }
1017:     } else if (def.breath) {
1018:       a.tickTimer = (a.tickTimer || 0) - dt;
1019:       if (a.tickTimer <= 0) {
1020:         a.tickTimer = def.tick || 0.3;
1021:         this._spawnBreath(player);
1022:         if (this._shapeHit(def.shape, player)) {
1023:           this.game.player.takeDamage(def.damage, this.pos, false);
1024:         }
