302: .item-readout{position:absolute;left:calc(18px + var(--safe-l));bottom:calc(168px + var(--safe-b));display:flex;align-items:center;gap:7px;font-size:8px;letter-spacing:.14em;color:#c5d3cc;text-shadow:0 1px 4px #000;opacity:.9}
