328: #stick-base{width:clamp(104px,17vmin,138px);height:clamp(104px,17vmin,138px);border-radius:50%;border:1.5px solid rgba(230,240,235,.25);background:radial-gradient(circle at 50% 45%,rgba(20,38,33,.5),rgba(5,12,10,.32));position:relative;touch-action:none;box-shadow:inset 0 0 26px rgba(0,0,0,.35)}
