333: .act-btn,.lock-btn{position:absolute;pointer-events:auto;border-radius:50%;border:1.5px solid rgba(240,248,244,.24);background:radial-gradient(circle at 38% 28%,rgba(42,68,60,.82),rgba(9,19,16,.86));color:#f0f5f2;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;touch-action:none;backdrop-filter:blur(4px);box-shadow:0 6px 20px rgba(0,0,0,.4),inset 0 1px 0 rgba(255,255,255,.14);transition:transform .07s,background .12s,border-color .12s;font-family:var(--font-body);padding:0}
