335: .act-icon{display:flex;align-items:center;justify-content:center}
336: .act-icon svg{width:clamp(20px,3.4vmin,30px);height:clamp(20px,3.4vmin,30px);stroke:#f3f8f5;fill:none;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round;filter:drop-shadow(0 1px 2px rgba(0,0,0,.5))}
