394:   playerHit({ part, base, def, worldPos, finisher, charged, demon }) {
395:     if (!this.monster || this.monster.dying || this.huntOver) return;
396:     const res = this.monster.damage(part.id, base, { finisher, charged });
397:     if (!res) return;
398:     const dmg = Math.round(res.damage);
399:     const cls = finisher || charged ? 'big' : part.weak ? 'weak' : part.mult < 1 ? 'resist' : '';
400:     this.ui.damage(this.project(worldPos), `${dmg}`, cls, part.weak ? 'WEAK' : (charged ? 'CHARGED' : ''));
401:     this.hitstop = Math.min(0.11, Math.max(this.hitstop, finisher || charged ? 0.075 : 0.032));
402:     this.audio.impact(Math.min(1.4, 0.55 + dmg / 60), !!part.weak);
403:     this.shake(def.shake ?? 0.2, 0.13);
404:     this.damageDealt += res.damage;
405:     if (res.broke) this.partsVersion++;
406:     if (res.enragedNow) {
407:       this.audio.setIntensity(2);
408:       this.musicIntensity = 2;
409:     }
410:     if (res.tiredNow) this.audio.setIntensity(1);
411:   }
