479:   spawnProjectile({ from, to, speed, radius, damage, color, type, onHit }) {
480:     const group = new THREE.Group();
481:     const core = new THREE.Mesh(new THREE.IcosahedronGeometry(radius, 1), new THREE.MeshBasicMaterial({ color }));
482:     const glow = new THREE.Mesh(new THREE.IcosahedronGeometry(radius * 1.8, 1), new THREE.MeshBasicMaterial({
483:       color, transparent: true, opacity: 0.3, blending: THREE.AdditiveBlending, depthWrite: false,
484:     }));
485:     group.add(core, glow);
486:     group.position.copy(from);
487:     this.scene.add(group);
488:     const dir = to.clone().sub(from);
489:     const distance = Math.max(1, dir.length());
490:     dir.normalize();
491:     this.projectiles.push({
492:       mesh: group, core, glow, from: from.clone(), to: to.clone(), dir, speed,
493:       traveled: 0, distance, damage, radius, onHit, color, type, life: 4,
494:     });
495:     this.audio.whoosh?.();
496:   }
497: 
498:   updateProjectiles(dt) {
499:     for (let i = this.projectiles.length - 1; i >= 0; i--) {
500:       const p = this.projectiles[i];
501:       const step = p.speed * dt;
502:       p.traveled += step;
503:       p.mesh.position.addScaledVector(p.dir, step);
504:       p.mesh.position.y = p.from.y + (p.to.y - p.from.y) * Math.min(1, p.traveled / p.distance);
505:       p.mesh.rotation.x += dt * 6;
506:       p.mesh.rotation.y += dt * 4;
507:       p.glow.material.opacity = 0.25 + Math.sin(this.time * 20) * 0.07;
508:       if (Math.random() < dt * 40) {
509:         this.fx.burst(p.mesh.position, p.color, 1, 0.7, 1, { life: 0.35, gravity: 0, up: 0.1 });
510:       }
511:       const pc = this.player?.pos;
512:       const hitPlayer = pc && Math.hypot(pc.x - p.mesh.position.x, pc.z - p.mesh.position.z) < p.radius + 0.7;
513:       if (p.traveled >= p.distance || hitPlayer || p.life <= 0) {
514:         p.onHit?.(p.mesh.position.clone());
515:         this.fx.burst(p.mesh.position, p.color, 14, 5, 1, { life: 0.5, gravity: 2 });
516:         this.scene.remove(p.mesh);
517:         p.mesh.traverse?.((o) => { o.geometry?.dispose(); o.material?.dispose?.(); });
518:         this.projectiles.splice(i, 1);
519:       }
520:       p.life -= dt;
521:     }
522:   }
523: 
524:   spawnZone({ pos, radius, duration, dps, slow, color = 0x6fd8ff }) {
525:     const group = new THREE.Group();
526:     group.position.set(pos.x, 0.06, pos.z);
527:     const ring = new THREE.Mesh(new THREE.RingGeometry(radius * 0.9, radius, 40), new THREE.MeshBasicMaterial({
528:       color, transparent: true, opacity: 0.5, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false,
529:     }));
530:     ring.rotation.x = -Math.PI / 2;
531:     const fill = new THREE.Mesh(new THREE.CircleGeometry(radius, 36), new THREE.MeshBasicMaterial({
532:       color, transparent: true, opacity: 0.1, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false,
533:     }));
534:     fill.rotation.x = -Math.PI / 2;
535:     group.add(ring, fill);
536:     this.scene.add(group);
537:     this.zones.push({ mesh: group, ring, fill, pos: pos.clone(), radius, remaining: duration, dps, slow, tick: 0, color });
538:     this.fx.shockwave(pos, radius, color, 0.7);
539:   }
540: 
541:   updateZones(dt) {
542:     for (let i = this.zones.length - 1; i >= 0; i--) {
543:       const z = this.zones[i];
544:       z.remaining -= dt;
545:       z.tick -= dt;
546:       const f = Math.max(0, z.remaining / 5.5);
547:       z.ring.material.opacity = 0.35 + Math.sin(this.time * 6) * 0.12;
548:       z.mesh.rotation.y += dt * 0.35;
549:       const pc = this.player?.pos;
550:       const inside = pc && Math.hypot(pc.x - z.pos.x, pc.z - z.pos.z) < z.radius;
551:       if (inside) {
552:         this.player.slowTimer = 0.8;
553:         if (z.tick <= 0) {
554:           z.tick = 0.9;
555:           this.player.takeDamage(z.dps, z.pos, false);
556:           this.ui.subtitle('Frozen ground saps your strength', 1.2);
557:         }
558:         if (Math.random() < dt * 18) {
559:           this.fx.burst(new THREE.Vector3(pc.x + (Math.random() - 0.5) * 1.5, 0.4, pc.z + (Math.random() - 0.5) * 1.5), z.color, 1, 0.8, 1, { life: 0.6, gravity: 6 });
560:         }
561:       }
562:       if (Math.random() < dt * 10) {
563:         const a = Math.random() * Math.PI * 2, r = Math.random() * z.radius;
564:         this.fx.burst(new THREE.Vector3(z.pos.x + Math.cos(a) * r, 0.2 + Math.random() * 1.2, z.pos.z + Math.sin(a) * r), z.color, 1, 0.5, 1, { life: 0.8, gravity: -1 });
565:       }
566:       if (z.remaining <= 0) {
567:         this.scene.remove(z.mesh);
568:         z.mesh.traverse?.((o) => { o.geometry?.dispose(); o.material?.dispose?.(); });
569:         this.zones.splice(i, 1);
570:       }
571:     }
572:   }
573: 
574:   // ------------------------------------------------------------
575:   // update loop
576:   // ------------------------------------------------------------
577:   loop(now) {
578:     const raw = (now - this.last) / 1000;
579:     this.last = now;
580:     const dt = Math.min(0.05, Math.max(0.0001, raw));
581:     this.time += dt;
582:     if (this.state === 'hunt') this.updateHunt(dt);
583:     else if (this.state === 'result') this.updateResult(dt);
584:     else if (this.state === 'pause') {
585:       if (this.arena) this.arena.update(dt, this.time, this.player?.pos);
586:       this.fx.update(dt);
587:     } else {
588:       this.updateHub(dt);
589:     }
590:     this.renderer.render(this.scene, this.camera);
591:     requestAnimationFrame(this.loop);
592:   }
593: 
594:   updateHub(dt) {
595:     if (!this.arena || !this.player) return;
596:     this.hubTime += dt;
597:     this.arena.update(dt, this.time, this.player.pos);
598:     this.player._animate(dt, null, this.camera, null);
599:     this.fx.update(dt);
600:     const target = new THREE.Vector3(this.player.pos.x, 1.25, this.player.pos.z);
601:     const yaw = 0.32 + Math.sin(this.time * 0.11) * 0.18;
602:     const pitch = 0.17;
603:     const dist = this.state === 'title' ? 6.4 : 7.2;
604:     const desired = new THREE.Vector3(
605:       target.x + Math.sin(yaw) * dist * Math.cos(pitch),
606:       target.y + 1.1 + Math.sin(pitch) * dist,
607:       target.z + Math.cos(yaw) * dist * Math.cos(pitch)
608:     );
609:     this.camera.position.lerp(desired, 1 - Math.exp(-dt * 3));
610:     const right = new THREE.Vector3(-Math.cos(yaw + Math.PI / 2), 0, Math.sin(yaw + Math.PI / 2));
611:     const look = target.clone();
612:     if (this.state === 'title') look.addScaledVector(right, -2.4);
613:     this.camera.lookAt(look);
614:   }
615: 
616:   updateHunt(dt) {
617:     if (!this.arena || !this.player || !this.monster) return;
618:     if (this.input.consume('lock')) this.toggleLock();
619:     this.arena.update(dt, this.time, this.player.pos);
620:     this.fx.update(dt);
621: 
622:     if (this.intro > 0) {
623:       this.intro -= dt;
624:       const t = clamp(1 - this.intro / 3.0, 0, 1);
625:       this.monster._animate(dt, this.player);
626:       this.player._animate(dt, null, this.camera, null);
627:       this.updateIntroCamera(t, dt);
628:       if (!this.introRoared && t > 0.12) {
629:         this.introRoared = true;
630:         this.audio.roar(true);
631:         this.shake(0.55, 0.6);
632:         this.fx.shockwave(this.monster.pos, 8, 0xffd9a0, 0.9);
633:         this.fx.dust(new THREE.Vector3(this.monster.pos.x, 0.2, this.monster.pos.z), 20, 0x9a8a72);
634:       }
635:       if (this.intro <= 0) {
636:         this.monster.state = 'chase';
637:         this.monster.think = 0.6;
638:         this.hintControls();
639:       }
640:       this.updateHud();
641:       return;
642:     }
643: 
644:     if (this.huntOver) {
645:       this.resultDelay -= dt;
646:       this.monster.update(dt, this.player);
647:       this.player._animate(dt, null, this.camera, null);
648:       this.updateCamera(dt);
649:       this.updateHud();
650:       if (this.resultDelay <= 0 && this.state === 'hunt') this.finishHunt(this.hunt.reason === 'kill');
651:       return;
652:     }
653: 
654:     // quest timer
655:     this.hunt.timeLeft -= dt;
656:     if (this.hunt.timeLeft <= 0) {
657:       this.hunt.timeLeft = 0;
658:       this.huntOver = true;
659:       this.hunt.won = false;
660:       this.hunt.reason = 'timeout';
661:       this.resultDelay = 2.0;
662:       this.input.setEnabled(false);
663:       this.input.exitPointerLock();
664:       this.audio.stopMusic();
665:       this.ui.announce('TIME EXPIRED', '', 2.4);
666:       this.huntOver = true;
667:       return;
668:     }
669: 
670:     if (this.hitstop > 0) this.hitstop = Math.max(0, this.hitstop - dt);
671:     const simDt = this.hitstop > 0 ? dt * 0.06 : dt;
672: 
673:     this.player.update(simDt, this.input, this.camera, this.monster);
674:     this.monster.update(simDt, this.player);
675:     this.resolveBodies();
676:     this.updateProjectiles(simDt);
677:     this.updateZones(simDt);
678:     this.updateCamera(dt);
679:     this.updateHud();
680:   }
681: 
682:   updateResult(dt) {
683:     if (this.arena) this.arena.update(dt, this.time, this.player?.pos);
684:     this.fx.update(dt);
685:     if (this.monster) this.monster.update(dt, this.player || { pos: this.monster.pos });
686:     if (this.player) this.player._animate(dt, null, this.camera, null);
687:     // slow orbit around the aftermath
688:     const t = this.time * 0.13;
689:     const center = new THREE.Vector3();
690:     if (this.player) center.add(this.player.pos);
691:     if (this.monster) center.add(this.monster.pos);
692:     center.multiplyScalar(this.monster && this.player ? 0.5 : 1);
693:     center.y = 1.6;
694:     const yaw = t + 0.8;
695:     const dist = 11;
696:     const desired = new THREE.Vector3(
697:       center.x + Math.sin(yaw) * dist,
698:       center.y + 4.2,
699:       center.z + Math.cos(yaw) * dist
700:     );
701:     this.camera.position.lerp(desired, 1 - Math.exp(-dt * 1.4));
702:     this.camera.lookAt(center);
703:   }
704: 
705:   resolveBodies() {
706:     if (!this.player || !this.monster || this.monster.dead) return;
707:     const dx = this.player.pos.x - this.monster.pos.x;
708:     const dz = this.player.pos.z - this.monster.pos.z;
709:     const dist = Math.hypot(dx, dz);
710:     const min = this.monster.type.radius * 0.82 + 0.45;
711:     if (dist < min && dist > 0.001) {
712:       const push = min - dist;
713:       this.player.pos.x += (dx / dist) * push;
714:       this.player.pos.z += (dz / dist) * push;
715:       this.player.root.position.set(this.player.pos.x, 0, this.player.pos.z);
716:     }
717:   }
718: 
719:   updateIntroCamera(t, dt) {
720:     const ease = t * t * (3 - 2 * t);
721:     const yaw = 2.7 * (1 - ease);
722:     const pitch = 0.08 + 0.2 * ease;
723:     const dist = 11 - 3 * ease;
724:     const target = new THREE.Vector3(this.player.pos.x, 1.4, this.player.pos.z);
725:     const mc = this.monster.center;
726:     const look = target.clone().lerp(mc, Math.sin(t * Math.PI) * 0.55);
727:     const desired = new THREE.Vector3(
