}
#minimap{display:block;width:142px;height:142px;border-radius:50%}
.map-open-btn{
  position:absolute;right:-3px;top:0;pointer-events:auto;display:flex;align-items:center;gap:3px;
  border:1px solid rgba(232,180,90,.4);background:rgba(5,12,10,.82);color:var(--gold-hi);
  border-radius:999px;padding:4px 8px 4px 6px;font-size:7px;letter-spacing:.16em;font-weight:800;cursor:pointer;
  backdrop-filter:blur(6px);box-shadow:0 4px 14px rgba(0,0,0,.4)
}
.map-open-btn:hover{border-color:var(--gold-hi);background:rgba(30,24,10,.9)}
.map-open-btn svg{width:11px;height:11px;stroke:var(--gold);fill:none;stroke-width:1.7}
.minimap-clock{
  display:flex;align-items:center;justify-content:space-between;gap:5px;height:22px;margin-top:-2px;
  padding:0 8px;border:1px solid var(--line);border-radius:999px;background:rgba(5,12,10,.78);
  backdrop-filter:blur(7px);font-size:7px;letter-spacing:.12em;color:#a9bbb3;font-weight:700
}
.minimap-clock b{font-family:var(--font-title);font-size:11px;letter-spacing:.06em;color:#f4efe2;font-weight:400}
.minimap-clock #world-phase{color:var(--gold)}

.camp-menu-btn{
  position:absolute;top:calc(16px + env(safe-area-inset-top,0px));left:calc(18px + var(--safe-l));
  pointer-events:auto;cursor:pointer;border:1px solid var(--line);background:rgba(5,12,10,.68);
  color:#d5e0da;border-radius:7px;padding:9px 13px;font:700 9px/1 var(--font-body);letter-spacing:.18em;
  backdrop-filter:blur(8px);box-shadow:0 6px 20px rgba(0,0,0,.35)
}
.camp-menu-btn:hover{border-color:var(--gold);color:var(--gold-hi)}

.interact-prompt{
  position:absolute;left:50%;bottom:calc(196px + var(--safe-b));transform:translateX(-50%);
  pointer-events:auto;cursor:pointer;display:flex;align-items:center;gap:9px;text-align:left;
  border:1px solid rgba(232,180,90,.5);background:rgba(6,14,11,.88);border-radius:10px;
  padding:9px 14px 9px 10px;color:#eef3ee;backdrop-filter:blur(10px);
  box-shadow:0 10px 30px rgba(0,0,0,.45),0 0 24px rgba(232,180,90,.1);animation:promptIn .18s ease-out
}
