.interact-prompt b{font-size:11px;letter-spacing:.08em;font-weight:700}
.interact-prompt small{font-size:8px;letter-spacing:.14em;color:#9fb0a9;text-transform:uppercase}
@keyframes promptIn{from{opacity:0;transform:translate(-50%,8px)}to{opacity:1;transform:translate(-50%,0)}}

/* full map */
.map-screen{
