}
.map-foot{justify-content:space-between;align-items:center;gap:12px}
.map-foot .btn{padding:9px 14px;font-size:9px}

/* item box */
.items-wrap{display:grid;grid-template-columns:minmax(210px,300px) minmax(0,520px);gap:16px;justify-content:center;align-items:start;padding:12px 4px}
