.stash-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin-top:12px}
.stash-row{display:flex;align-items:center;gap:8px;background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.07);border-radius:7px;padding:9px 10px;font-size:10px;color:#cbd8d1}
.stash-row b{margin-left:auto;font-size:13px;color:var(--gold-hi)}
.stash-dot{width:9px;height:9px;border-radius:50%;flex:none;box-shadow:0 0 8px currentColor}

/* ============ HUD spacing / touch fixes ============ */
.hud-player{max-width:36vw}
.hud-bars{width:min(250px,30vw)}
.hud-monster{width:min(520px,40vw)}
.hud-lock{top:calc(92px + env(safe-area-inset-top,0px));bottom:auto;padding:3px 8px;border:1px solid rgba(232,180,90,.22);border-radius:999px;background:rgba(5,12,10,.45)}
.hud-lock.hidden{display:none!important}

@media (max-width:980px){
  .hud-player{top:calc(12px + env(safe-area-inset-top,0px));max-width:46vw}
  .hud-bars{width:min(230px,34vw)}
  .hud-monster{top:calc(82px + env(safe-area-inset-top,0px));width:min(72vw,470px)}
  .hud-quest{top:calc(12px + env(safe-area-inset-top,0px))}
