  .hud-quest{top:calc(10px + env(safe-area-inset-top,0px))}
  .hud-lock{top:calc(132px + env(safe-area-inset-top,0px))}
  .minimap-wrap{width:118px;height:140px}
  #minimap{width:118px;height:118px}
  .map-foot{flex-direction:column}
