  .stash-grid{grid-template-columns:1fr}
}
@media (max-width:520px) and (orientation:portrait){
  .minimap-wrap{left:auto;right:calc(10px + var(--safe-r));bottom:calc(284px + var(--safe-b));width:104px;height:126px}
  #minimap{width:104px;height:104px}
}
body.touch-mode .minimap-wrap{
  left:auto;right:calc(10px + var(--safe-r));bottom:calc(286px + var(--safe-b));
  width:106px;height:128px
}
