body.touch-mode .interact-prompt{bottom:calc(318px + var(--safe-b))}
body.touch-mode .camp-menu-btn{top:calc(10px + env(safe-area-inset-top,0px))}
body.lefty .minimap-wrap{left:calc(18px + var(--safe-l));right:auto}
body.lefty .camp-menu-btn{left:auto;right:calc(18px + var(--safe-r))}

@media (max-height:520px) and (orientation:landscape){
  .hud-monster{top:10px!important;width:42vw!important}
