import { createRequire } from 'node:module';
import { mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const out = '/tmp/opencode/shots';
mkdirSync(out, { recursive: true });
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', e => { errors.push(e.message); console.log('PAGEERROR', e.message); });
page.on('console', m => { if (m.type() === 'error') { errors.push(m.text()); console.log('CONSOLE', m.text()); } });
await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load' });
await page.waitForTimeout(2500);
console.log('title state', await page.evaluate(() => window.game?.state));
await page.screenshot({ path: join(out, '01-title.png') });
await page.click('[data-nav="hub"]');
await page.waitForTimeout(1800);
console.log('hub state', await page.evaluate(() => window.game?.state));
await page.screenshot({ path: join(out, '02-hub.png') });
await page.click('#enter-camp');
await page.waitForTimeout(1600);
console.log('camp state', await page.evaluate(() => ({ state: window.game?.state, pos: window.game?.player?.pos, y: window.game?.player?.root?.position?.y })));
await page.screenshot({ path: join(out, '03-camp.png') });
await page.keyboard.down('KeyW');
await page.waitForTimeout(700);
await page.keyboard.up('KeyW');
await page.waitForTimeout(300);
console.log('after move', await page.evaluate(() => ({ pos: window.game?.player?.pos, y: window.game?.player?.root?.position?.y, cam: window.game?.camera?.position })));
await page.click('#map-open');
await page.waitForTimeout(700);
console.log('map state', await page.evaluate(() => ({ state: window.game?.state, open: window.game?.mapOpen })));
await page.screenshot({ path: join(out, '04-map.png') });
await page.click('#map-close');
await page.waitForTimeout(600);
console.log('after map close', await page.evaluate(() => ({ state: window.game?.state, open: window.game?.mapOpen })));
// teleport next to the quest board and interact
await page.evaluate(() => {
  const g = window.game;
  g.player.pos.set(-9, 0, -5.4);
  g.player.setPosition(g.player.pos);
});
await page.waitForTimeout(400);
console.log('near station', await page.evaluate(() => ({ near: window.game?.nearStation?.id, prompt: document.getElementById('interact-label')?.textContent })));
await page.keyboard.press('KeyE');
await page.waitForTimeout(700);
console.log('after interact', await page.evaluate(() => ({ state: window.game?.state, screen: window.game?.ui?.screen })));
await page.screenshot({ path: join(out, '05-quests.png') });
// start hunt directly
await page.evaluate(() => window.game.startHunt('forest'));
await page.waitForTimeout(1200);
console.log('hunt state', await page.evaluate(() => ({ state: window.game?.state, px: window.game?.player?.pos.x, pz: window.game?.player?.pos.z, py: window.game?.player?.root?.position?.y, mx: window.game?.monster?.pos.x, mz: window.game?.monster?.pos.z, my: window.game?.monster?.root?.position?.y, chunks: window.game?.world?.stats?.chunks, obstacles: window.game?.world?.stats?.obstacles })));
await page.screenshot({ path: join(out, '06-hunt-intro.png') });
await page.waitForTimeout(4500);
console.log('hunt running', await page.evaluate(() => ({ state: window.game?.state, hp: window.game?.player?.hp, mstate: window.game?.monster?.state, time: window.game?.hunt?.timeLeft, chunks: window.game?.world?.stats?.chunks, hiProps: window.game?.world?.stats?.hiProps, pooled: window.game?.world?.stats?.pooled, clock: window.game?.world?.clock() })));
await page.screenshot({ path: join(out, '07-hunt.png') });
console.log('ERRORS', JSON.stringify(errors));
await browser.close();

